--
-- Name: space_view; Type: MATERIALIZED VIEW; Schema: ows; Owner: agdc_manage
--

CREATE MATERIALIZED VIEW ows.space_view AS
 WITH metadata_lookup AS (
         SELECT metadata_type.id,
            metadata_type.name
           FROM agdc.metadata_type
        ), eo3_ranges AS (
         SELECT dataset.id,
            (dataset.metadata #>> '{extent,lat,begin}'::text[]) AS lat_begin,
            (dataset.metadata #>> '{extent,lat,end}'::text[]) AS lat_end,
            (dataset.metadata #>> '{extent,lon,begin}'::text[]) AS lon_begin,
            (dataset.metadata #>> '{extent,lon,end}'::text[]) AS lon_end,
            public.st_transform(public.st_setsrid(public.st_geomfromgeojson((dataset.metadata #>> '{geometry}'::text[])), (substr((dataset.metadata #>> '{crs}'::text[]), 6))::integer), 4326) AS valid_geom
           FROM agdc.dataset
          WHERE ((dataset.metadata_type_ref IN ( SELECT metadata_lookup.id
                   FROM metadata_lookup
                  WHERE ((metadata_lookup.name)::text = 'eo3'::text))) AND (dataset.archived IS NULL) AND (upper(substr((dataset.metadata #>> '{crs}'::text[]), 1, 5)) = 'EPSG:'::text))
        ), eo_corners AS (
         SELECT dataset.id,
            (dataset.metadata #>> '{extent,coord,ll,lat}'::text[]) AS ll_lat,
            (dataset.metadata #>> '{extent,coord,ll,lon}'::text[]) AS ll_lon,
            (dataset.metadata #>> '{extent,coord,lr,lat}'::text[]) AS lr_lat,
            (dataset.metadata #>> '{extent,coord,lr,lon}'::text[]) AS lr_lon,
            (dataset.metadata #>> '{extent,coord,ul,lat}'::text[]) AS ul_lat,
            (dataset.metadata #>> '{extent,coord,ul,lon}'::text[]) AS ul_lon,
            (dataset.metadata #>> '{extent,coord,ur,lat}'::text[]) AS ur_lat,
            (dataset.metadata #>> '{extent,coord,ur,lon}'::text[]) AS ur_lon
           FROM agdc.dataset
          WHERE ((dataset.metadata_type_ref IN ( SELECT metadata_lookup.id
                   FROM metadata_lookup
                  WHERE ((metadata_lookup.name)::text = ANY ((ARRAY['eo'::character varying, 'eo_s2_nrt'::character varying, 'gqa_eo'::character varying, 'eo_plus'::character varying, 'boku'::character varying])::text[])))) AND (dataset.archived IS NULL) AND (((dataset.metadata #>> '{grid_spatial,projection,valid_data}'::text[]) IS NULL) OR (upper(substr((dataset.metadata #>> '{grid_spatial,projection,spatial_reference}'::text[]), 1, 5)) <> 'EPSG:'::text)))
        ), eo_geoms AS (
         SELECT dataset.id,
            public.st_transform(public.st_setsrid(public.st_geomfromgeojson((dataset.metadata #>> '{grid_spatial,projection,valid_data}'::text[])), (substr((dataset.metadata #>> '{grid_spatial,projection,spatial_reference}'::text[]), 6))::integer), 4326) AS valid_data
           FROM agdc.dataset
          WHERE ((dataset.metadata_type_ref IN ( SELECT metadata_lookup.id
                   FROM metadata_lookup
                  WHERE ((metadata_lookup.name)::text = ANY ((ARRAY['eo'::character varying, 'eo_s2_nrt'::character varying, 'gqa_eo'::character varying, 'eo_plus'::character varying, 'boku'::character varying])::text[])))) AND (dataset.archived IS NULL) AND ((dataset.metadata #>> '{grid_spatial,projection,valid_data}'::text[]) IS NOT NULL) AND (upper(substr((dataset.metadata #>> '{grid_spatial,projection,spatial_reference}'::text[]), 1, 5)) = 'EPSG:'::text))
        )
 SELECT eo3_ranges.id,
    (format('POLYGON(( %s %s, %s %s, %s %s, %s %s, %s %s))'::text, eo3_ranges.lon_begin, eo3_ranges.lat_begin, eo3_ranges.lon_end, eo3_ranges.lat_begin, eo3_ranges.lon_end, eo3_ranges.lat_end, eo3_ranges.lon_begin, eo3_ranges.lat_end, eo3_ranges.lon_begin, eo3_ranges.lat_begin))::public.geometry AS spatial_extent
   FROM eo3_ranges
  WHERE (eo3_ranges.valid_geom IS NULL)
UNION
 SELECT eo3_ranges.id,
    eo3_ranges.valid_geom AS spatial_extent
   FROM eo3_ranges
  WHERE (eo3_ranges.valid_geom IS NOT NULL)
UNION
 SELECT eo_corners.id,
    (format('POLYGON(( %s %s, %s %s, %s %s, %s %s, %s %s))'::text, eo_corners.ll_lon, eo_corners.ll_lat, eo_corners.lr_lon, eo_corners.lr_lat, eo_corners.ur_lon, eo_corners.ur_lat, eo_corners.ul_lon, eo_corners.ul_lat, eo_corners.ll_lon, eo_corners.ll_lat))::public.geometry AS spatial_extent
   FROM eo_corners
UNION
 SELECT eo_geoms.id,
    eo_geoms.valid_data AS spatial_extent
   FROM eo_geoms
UNION
 SELECT dataset.id,
    public.st_transform(public.st_setsrid(public.st_geomfromgeojson((dataset.metadata #>> '{geometry}'::text[])), (substr((dataset.metadata #>> '{crs}'::text[]), 6))::integer), 4326) AS spatial_extent
   FROM agdc.dataset
  WHERE ((dataset.metadata_type_ref IN ( SELECT metadata_lookup.id
           FROM metadata_lookup
          WHERE ((metadata_lookup.name)::text ~~ 'eo3_%'::text))) AND (upper(substr((dataset.metadata #>> '{grid_spatial,projection,spatial_reference}'::text[]), 1, 5)) = 'EPSG:'::text) AND (dataset.archived IS NULL))
  WITH NO DATA;


ALTER MATERIALIZED VIEW ows.space_view OWNER TO agdc_manage;

--
-- Name: time_view; Type: MATERIALIZED VIEW; Schema: ows; Owner: agdc_manage
--

CREATE MATERIALIZED VIEW ows.time_view AS
 WITH metadata_lookup AS (
         SELECT metadata_type.id,
            metadata_type.name
           FROM agdc.metadata_type
        )
 SELECT dataset.dataset_type_ref,
    dataset.id,
        CASE
            WHEN (((dataset.metadata -> 'extent'::text) ->> 'from_dt'::text) IS NULL) THEN tstzrange(((((dataset.metadata -> 'extent'::text) ->> 'center_dt'::text))::timestamp without time zone)::timestamp with time zone, ((((dataset.metadata -> 'extent'::text) ->> 'center_dt'::text))::timestamp without time zone)::timestamp with time zone, '[]'::text)
            ELSE tstzrange(((((dataset.metadata -> 'extent'::text) ->> 'from_dt'::text))::timestamp without time zone)::timestamp with time zone, ((((dataset.metadata -> 'extent'::text) ->> 'to_dt'::text))::timestamp without time zone)::timestamp with time zone, '[]'::text)
        END AS temporal_extent
   FROM agdc.dataset
  WHERE ((dataset.metadata_type_ref IN ( SELECT metadata_lookup.id
           FROM metadata_lookup
          WHERE ((metadata_lookup.name)::text = ANY ((ARRAY['eo'::character varying, 'eo_s2_nrt'::character varying, 'gqa_eo'::character varying, 'eo_plus'::character varying])::text[])))) AND (dataset.archived IS NULL))
UNION
 SELECT dataset.dataset_type_ref,
    dataset.id,
    tstzrange(((COALESCE(((dataset.metadata -> 'properties'::text) ->> 'dtr:start_datetime'::text), ((dataset.metadata -> 'properties'::text) ->> 'datetime'::text)))::timestamp without time zone)::timestamp with time zone, (COALESCE((((dataset.metadata -> 'properties'::text) ->> 'dtr:end_datetime'::text))::timestamp without time zone, (((dataset.metadata -> 'properties'::text) ->> 'datetime'::text))::timestamp without time zone))::timestamp with time zone, '[]'::text) AS temporal_extent
   FROM agdc.dataset
  WHERE ((dataset.metadata_type_ref IN ( SELECT metadata_lookup.id
           FROM metadata_lookup
          WHERE ((metadata_lookup.name)::text ~~ 'eo3%'::text))) AND (dataset.archived IS NULL))
  WITH NO DATA;


ALTER MATERIALIZED VIEW ows.time_view OWNER TO agdc_manage;

--
-- Name: space_time_view; Type: MATERIALIZED VIEW; Schema: ows; Owner: agdc_manage
--

CREATE MATERIALIZED VIEW ows.space_time_view AS
 SELECT space_view.id,
    time_view.dataset_type_ref,
    space_view.spatial_extent,
    time_view.temporal_extent
   FROM (ows.space_view
     JOIN ows.time_view ON ((space_view.id = time_view.id)))
  WITH NO DATA;


ALTER MATERIALIZED VIEW ows.space_time_view OWNER TO agdc_manage;

